#!/usr/bin/env python3
"""Generate the Kigen Dart token layers from the Figma exports in design/.

    python3 tool/gen_kigen.py            # write lib/theme/kigen/*.dart
    python3 tool/gen_kigen.py --check    # verify committed Dart matches design/

Committed on purpose. The three files it writes total ~1285 lines and are marked
"do not edit by hand" — without this script a Figma re-export means editing all
of them by hand, and the resolution decisions below become unrecoverable. Re-run
this after every export instead.

Inputs (W3C design-token JSON, resolved values, no aliases):

    design/Value.tokens 2.json       66 primitives, 6 hues x 11 stops
    design/semantic-light.tokens.json  60 roles, light mode
    design/semantic-dark.tokens.json   60 roles, dark mode
    design/Value.tokens 3.json       184 component tokens (light only)

Outputs:

    lib/theme/kigen/kigen_primitives.dart
    lib/theme/kigen/kigen_semantic.dart
    lib/theme/kigen/kigen_component.dart

The exports carry no `com.figma.aliasOf` metadata, so every value is a resolved
hex and the links between layers have to be recovered by matching hex. That is
exact for the primitive -> semantic step (58 of 60; the 2 Overlay tokens carry
alpha and stay literal). For semantic -> component it is ambiguous -- #FFFFFF
alone is ten different light-mode semantic tokens -- so the component field's own
name picks the group, and anything still ambiguous is listed in OVERRIDES below.
"""

from __future__ import annotations

import json
import re
import subprocess
import sys
import tempfile
from collections import OrderedDict
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DESIGN = ROOT / "design"
OUT = ROOT / "lib" / "theme" / "kigen"

PRIMITIVES_JSON = DESIGN / "Value.tokens 2.json"
SEMANTIC_LIGHT_JSON = DESIGN / "semantic-light.tokens.json"
SEMANTIC_DARK_JSON = DESIGN / "semantic-dark.tokens.json"
COMPONENT_JSON = DESIGN / "Value.tokens 3.json"

HEADER = """// GENERATED by tool/gen_kigen.py -- do not edit by hand.
// Source: {source}
// Regenerate: python3 tool/gen_kigen.py
"""

# Figma hue group -> Dart field prefix.
HUES = OrderedDict(
    [
        ("Primary", "primary"),
        ("Neutral", "neutral"),
        ("Success", "success"),
        ("Warning", "warning"),
        ("Error", "error"),
        ("Info", "info"),
    ]
)
STOPS = ["50", "100", "200", "300", "400", "500", "600", "700", "800", "900", "950"]

# Figma names that do not survive mechanical camel-casing.
SEMANTIC_NAME_OVERRIDES = {
    # Figma authoring typo, kept out of the Dart surface.
    "Background/Brandsubtal": "backgroundBrandSubtle",
    # The "- BG" suffix is redundant inside a group already called Background.
    "Background/Secondary - BG": "backgroundSecondary",
}

# Component tokens the group rule gets wrong. Read off the --report output; each
# entry is a deliberate reading of what the control does, and each is here
# because the export gives two roles the same light-mode hex while they disagree
# in dark. Keep this list short -- if it grows, fix ROLE_RULES instead.
COMPONENT_OVERRIDES = {
    # Text sitting on a fill that is the SAME colour in both modes (brand blue,
    # destructive red). It has to stay light in both, so it reads Text/Inverse
    # Light (#FFFFFF always), not Text/Inverse Dark (which flips to #000000 and
    # would put black text on a blue button in dark mode). Text on
    # Background/Inverse -- secondary button, snackbar, tooltip -- correctly
    # keeps Inverse Dark, because that background flips too.
    "Button/Primary/Text": "textInverseLight",
    "Button/Destructive/Text": "textInverseLight",
    "Checkbox/CheckedText": "textInverseLight",
    "Calendar/SelectedText": "textInverseLight",
    # Validation messages under a field, not the field's own border.
    "Input/Error": "textError",
    "Input/Success": "textSuccess",
    # A hovered input restyles its outline; the name says Hover, so the group
    # rule reaches for a background.
    "Input/Hover": "borderStrong",
    # The current crumb is a label. Tabs/Active, which the same rule catches, is
    # genuinely a background and is left alone.
    "Breadcrumb/Active": "textPrimary",
}

# Which semantic groups a component field may resolve into, keyed by how its
# last path segment reads. First matching rule wins; groups are tried in order.
ROLE_RULES = [
    (r"(Border|Line|Focus)$", ["Border"]),
    (r"^Icon$", ["Icon", "Text"]),
    (r"(Text|Label|Placeholder|Helper|Title|Value|Action)", ["Text", "Icon"]),
    (r"(BG|Background|Track|Thumb|Fill|Header|Dot|Overlay|Shadow)$", ["Background", "Surface"]),
    (r"(Hover|Pressed|Selected|Active|Disabled)$", ["Background", "Surface"]),
    (r"(Success|Warning|Error|Info)$", ["Background", "Surface"]),
]
DEFAULT_GROUPS = ["Background", "Surface", "Text", "Border", "Icon"]


# ---------------------------------------------------------------- json loading


def leaves(node, path=""):
    """Yield (slash/path, token dict) for every leaf token."""
    if not isinstance(node, dict):
        return
    if "$value" in node:
        yield path, node
        return
    for key, value in node.items():
        if key.startswith("$"):
            continue
        yield from leaves(value, f"{path}/{key}" if path else key)


def load(path: Path) -> "OrderedDict[str, tuple[str, float]]":
    """path -> {token path: (upper-case #RRGGBB, alpha)} in file order."""
    with path.open() as handle:
        data = json.load(handle)
    out = OrderedDict()
    for token_path, token in leaves(data):
        value = token["$value"]
        # Alpha is kept at full precision on purpose. Figma writes 0.9 as
        # 0.8999999761581421, and 0.9 * 255 rounds to 230 while the real value
        # rounds to 229 — a rounding pass here silently shifts the scrims.
        out[token_path] = (value["hex"].upper(), float(value.get("alpha", 1)))
    return out


# ------------------------------------------------------------------- utilities


def dart_color(hex_rgb: str, alpha: float) -> str:
    """#RRGGBB + alpha -> a const Color literal."""
    a = max(0, min(255, round(alpha * 255)))
    return f"Color(0x{a:02X}{hex_rgb.lstrip('#').upper()})"


def camel(segments: list[str]) -> str:
    """['Button', 'Outline - Primary', 'BG'] -> 'buttonOutlinePrimaryBg'."""
    words = []
    for segment in segments:
        for word in re.split(r"[^A-Za-z0-9]+", segment):
            if word:
                words.append(word[0].upper() + word[1:])
    name = "".join(words)
    name = re.sub(r"BG\b", "Bg", name)
    return name[0].lower() + name[1:]


def semantic_name(token_path: str) -> str:
    if token_path in SEMANTIC_NAME_OVERRIDES:
        return SEMANTIC_NAME_OVERRIDES[token_path]
    return camel(token_path.split("/"))


def component_name(token_path: str) -> str:
    return camel(token_path.split("/"))


# --------------------------------------------------------------- layer 1: prims


def gen_primitives(primitives) -> str:
    by_path = {path: value for path, value in primitives.items()}
    fields, ctor, fallback, api = [], [], [], []

    for hue, prefix in HUES.items():
        fields.append(f"\n  // ---- {hue} ----")
        fallback.append(f"    // {hue}")
        api.append("")
        for stop in STOPS:
            name = f"{prefix}{stop}"
            hex_rgb, alpha = by_path[f"{hue}/{stop}"]
            fields.append(f"  final Color {name};")
            ctor.append(f"    required this.{name},")
            fallback.append(f"    {name}: {dart_color(hex_rgb, alpha)},")
            api.append(f"      {name}: p({prefix}, '{stop}'),")

    return f"""{HEADER.format(source=PRIMITIVES_JSON.name)}
import 'package:flutter/material.dart';

/// Layer 1 -- the raw palette: {len(HUES)} hue ramps x {len(STOPS)} stops, and nothing about
/// meaning.
///
/// **This is the only layer the backend can override** -- an admin's seed
/// colour touches [KigenPrimitives] and nothing else. Light/dark selection
/// happens one layer up, in [KigenSemanticColors].
///
/// [fallback] is the committed Figma export (brand `#0079FF`) and is what the
/// app runs on until `/api/theme` exists.
@immutable
class KigenPrimitives {{
{chr(10).join(fields)}

  const KigenPrimitives({{
{chr(10).join(ctor)}
  }});

  /// `#RRGGBB` (or `RRGGBB`) -> opaque [Color]. Tolerates a leading `#` and
  /// surrounding whitespace, which the API has been known to send.
  static Color _hex(String value) =>
      Color(int.parse('FF${{value.replaceAll('#', '').trim()}}', radix: 16));

  /// Build the ramp from the `/api/theme` colour maps. Each argument is
  /// `{{"50": "#..", ... "950": "#.."}}` and all {len(STOPS)} stops must be present. The API
  /// names two ramps `warn`/`info`; they land on warning/info here.
  factory KigenPrimitives.fromApiMaps({{
    required Map<String, dynamic> primary,
    required Map<String, dynamic> neutral,
    required Map<String, dynamic> success,
    required Map<String, dynamic> warn,
    required Map<String, dynamic> error,
    required Map<String, dynamic> info,
  }}) {{
    final Map<String, dynamic> warning = warn;
    Color p(Map<String, dynamic> ramp, String stop) => _hex(ramp[stop] as String);
    return KigenPrimitives({chr(10).join(api)}
    );
  }}

  /// The committed Figma palette. `const`, so it costs nothing to hold and can
  /// be used from context-free init code.
  static const KigenPrimitives fallback = KigenPrimitives(
{chr(10).join(fallback)}
  );
}}
"""


# ------------------------------------------------------------ layer 2: semantic

GROUP_DOCS = {
    "Background": "The page itself, behind everything.",
    "Surface": "Cards, sheets and rows that sit *on* the background.",
    "Text": "Every string the user reads.",
    "Border": "Outlines, dividers, hairlines.",
    "Icon": "Glyphs. Split from Text on purpose -- the export gives the status\n  /// icons a different stop than the status labels.",
    "Overlay": "Scrims behind modals and sheets. The only semantic tokens that\n  /// carry alpha, and so the only two not backed by a primitive stop.",
}


def gen_semantic(primitives, light, dark) -> str:
    prim_by_hex = {}
    for path, (hex_rgb, alpha) in primitives.items():
        if alpha == 1:
            prim_by_hex.setdefault(hex_rgb, path)

    def stop_expr(hex_rgb, alpha):
        """The `p.<field>` a semantic value reads, or None if it is a literal."""
        if alpha != 1:
            return None
        path = prim_by_hex.get(hex_rgb)
        if path is None:
            return None
        hue, stop = path.split("/")
        return f"p.{HUES[hue]}{stop}"

    fields, ctor, light_body, dark_body = [], [], [], []
    literals = []
    current_group = None

    for token_path in light:
        group = token_path.split("/")[0]
        name = semantic_name(token_path)
        if group != current_group:
            current_group = group
            doc = GROUP_DOCS.get(group, group)
            fields.append(f"\n  // ---- {group} ----\n  /// {doc}")
            light_body.append(f"    // {group}")
            dark_body.append(f"    // {group}")

        fields.append(f"  final Color {name};")
        ctor.append(f"    required this.{name},")

        for body, table in ((light_body, light), (dark_body, dark)):
            hex_rgb, alpha = table[token_path]
            expr = stop_expr(hex_rgb, alpha)
            if expr is None:
                expr = f"const {dart_color(hex_rgb, alpha)}"
                literals.append(token_path)
            body.append(f"    {name}: {expr},")

    return f"""{HEADER.format(source=f"{SEMANTIC_LIGHT_JSON.name} + {SEMANTIC_DARK_JSON.name}")}
import 'package:flutter/material.dart';

import 'kigen_primitives.dart';

/// Layer 2 -- roles. Each role names a job ("the colour of body text") and reads
/// one stop of a [KigenPrimitives] ramp.
///
/// **This is the only file where light and dark differ.** The token name never
/// changes; only which stop it reads. If a colour is right in one mode and wrong
/// in the other, there is exactly one file to open.
///
/// {len(literals) // 2} tokens are literals rather than primitive stops, because they carry
/// alpha and the primitive ramps are all opaque.
///
/// ## Four oddities in the export — reproduced on purpose, do not "fix" here
///
/// These look like bugs and probably are, but they are the design source's to
/// correct. Patching them in Dart would put the code and Figma out of sync, and
/// the next export would silently overwrite the patch anyway. Raised with the
/// designer; fix upstream.
///
/// - [surfaceSecondary] is `#FFFFFF` in **both** modes — a white card in dark.
/// - [surfaceTransparent] is opaque `#FFFFFF`; the name promises transparency.
/// - [textTertiary] in dark is `#FFFFFF`, the same as [textPrimary], so the
///   tertiary step disappears (in light it is a distinct `#BFBFBF`).
/// - [iconSuccess] / [iconWarning] / [iconError] / [iconInfo] hold stop 500 in
///   both modes, while [textSuccess] and friends drop to stop 400 in dark. A
///   status icon therefore reads darker than its own label on a dark surface.
///
/// Not oddities: [textInverseLight], [iconInverseLight] and [iconInverseDark]
/// are constant across modes by design — "always light" and "always dark" is
/// the whole point of them.
@immutable
class KigenSemanticColors {{
{chr(10).join(fields)}

  const KigenSemanticColors({{
{chr(10).join(ctor)}
  }});

  /// Light mode.
  factory KigenSemanticColors.light(KigenPrimitives p) => KigenSemanticColors(
{chr(10).join(light_body)}
  );

  /// Dark mode.
  factory KigenSemanticColors.dark(KigenPrimitives p) => KigenSemanticColors(
{chr(10).join(dark_body)}
  );
}}
"""


# ----------------------------------------------------------- layer 3: component


def resolve_component(token_path, hex_rgb, alpha, sem_by_hex, report):
    """Pick the semantic field a component token reads. None -> emit a literal."""
    if token_path in COMPONENT_OVERRIDES:
        return COMPONENT_OVERRIDES[token_path], "override"
    if alpha != 1:
        return None, "literal (alpha)"

    candidates = sem_by_hex.get(hex_rgb, [])
    if not candidates:
        return None, "literal (no semantic match)"

    last = token_path.split("/")[-1]
    groups = DEFAULT_GROUPS
    for pattern, preferred in ROLE_RULES:
        if re.search(pattern, last):
            groups = preferred + [g for g in DEFAULT_GROUPS if g not in preferred]
            break

    ranked = sorted(
        candidates,
        key=lambda path: (
            groups.index(path.split("/")[0]) if path.split("/")[0] in groups else 99,
            candidates.index(path),
        ),
    )
    chosen = ranked[0]
    if len(candidates) > 1:
        report.append((token_path, chosen, candidates))
    return semantic_name(chosen), "matched"


def gen_component(light, component, report) -> str:
    sem_by_hex = {}
    for path, (hex_rgb, alpha) in light.items():
        if alpha == 1:
            sem_by_hex.setdefault(hex_rgb, []).append(path)

    fields, ctor, body = [], [], []
    literal_count = 0
    current_group = None

    for token_path in component:
        hex_rgb, alpha = component[token_path]
        group = token_path.split("/")[0]
        name = component_name(token_path)
        if group != current_group:
            current_group = group
            fields.append(f"\n  // ---- {group} ----")
            body.append(f"    // {group}")

        fields.append(f"  final Color {name};")
        ctor.append(f"    required this.{name},")

        field, how = resolve_component(token_path, hex_rgb, alpha, sem_by_hex, report)
        if field is None:
            literal_count += 1
            body.append(f"    {name}: const {dart_color(hex_rgb, alpha)}, // {how}")
        else:
            body.append(f"    {name}: s.{field},")

    return f"""{HEADER.format(source=COMPONENT_JSON.name)}
import 'package:flutter/material.dart';

import 'kigen_semantic.dart';

/// Layer 3 -- the controls Figma models explicitly: buttons and their {len(fields) and 8} variants,
/// inputs, badges, alerts, and the rest.
///
/// Every field is derived from [KigenSemanticColors], never from a primitive, so
/// mode is already baked in by the time a value lands here. That matters because
/// the Figma export is **light-only** -- deriving from the semantic layer is what
/// gives these tokens a dark mode at all.
///
/// Reach for this layer only when rebuilding a control Figma drew. For anything
/// else the semantic layer is the right altitude.
@immutable
class KigenComponentColors {{
{chr(10).join(fields)}

  const KigenComponentColors({{
{chr(10).join(ctor)}
  }});

  /// Derive every control token from a resolved semantic layer. {literal_count} fields are
  /// literals: they carry alpha, which no semantic token outside Overlay does.
  factory KigenComponentColors.from(KigenSemanticColors s) =>
      KigenComponentColors(
{chr(10).join(body)}
      );
}}
"""


# ------------------------------------------------------------------------- main


def dart_format(sources: dict[str, str]) -> dict[str, str]:
    """Run `dart format` over the emitted files.

    Formatting here rather than leaving it to a later `dart format lib/` is what
    lets --check compare byte-for-byte: otherwise the first person to format the
    repo makes every generated file look stale.
    """
    with tempfile.TemporaryDirectory() as tmp:
        for name, text in sources.items():
            staged = Path(tmp) / name
            staged.parent.mkdir(parents=True, exist_ok=True)
            staged.write_text(text)
        result = subprocess.run(
            ["dart", "format", tmp],
            capture_output=True,
            text=True,
        )
        if result.returncode != 0:
            print(f"WARNING: dart format failed, emitting unformatted\n{result.stderr}")
            return sources
        return {name: (Path(tmp) / name).read_text() for name in sources}


def main() -> int:
    check = "--check" in sys.argv
    report_only = "--report" in sys.argv

    primitives = load(PRIMITIVES_JSON)
    light = load(SEMANTIC_LIGHT_JSON)
    dark = load(SEMANTIC_DARK_JSON)
    component = load(COMPONENT_JSON)

    missing = set(light) ^ set(dark)
    if missing:
        print(f"FATAL: light/dark token sets differ: {sorted(missing)}")
        return 1

    report: list = []
    outputs = dart_format(
        {
            "lib/theme/kigen/kigen_primitives.dart": gen_primitives(primitives),
            "lib/theme/kigen/kigen_semantic.dart": gen_semantic(
                primitives, light, dark
            ),
            "lib/theme/kigen/kigen_component.dart": gen_component(
                light, component, report
            ),
        }
    )

    print(
        f"primitives {len(primitives)}  semantic {len(light)}  component {len(component)}"
    )
    if report:
        print(f"\n{len(report)} component tokens had >1 candidate (group rule picked one):")
        for token_path, chosen, candidates in report:
            others = ", ".join(c for c in candidates if c != chosen)
            print(f"  {token_path:34s} -> {chosen:28s} (also: {others})")

    if report_only:
        return 0

    if check:
        stale = [
            name
            for name, text in outputs.items()
            if not (ROOT / name).exists() or (ROOT / name).read_text() != text
        ]
        for name in stale:
            print(f"STALE: {name}")
        print("Run: python3 tool/gen_kigen.py" if stale else "up to date")
        return 1 if stale else 0

    for name, text in outputs.items():
        path = ROOT / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(text)
        print(f"wrote {name}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
